-- Fresh initialized schema from 740df936887f40efc727a24b159064bfd4db34e5.
CREATE TABLE users (id TEXT PRIMARY KEY, api_key_hash TEXT UNIQUE NOT NULL, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, tier TEXT NOT NULL CHECK (tier IN ('free', 'pro')), daily_limit INTEGER NOT NULL DEFAULT 1000, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE upstream_accounts (id TEXT PRIMARY KEY, name TEXT UNIQUE NOT NULL, provider TEXT NOT NULL CHECK (provider IN ('anthropic', 'openai', 'google')), credential_type TEXT NOT NULL CHECK (credential_type IN ('cookie', 'api_key', 'session_token', 'oauth')), credentials TEXT NOT NULL, meta TEXT, quota_info TEXT, status TEXT NOT NULL CHECK (status IN ('active', 'quota_exceeded', 'error', 'disabled')), state_revision INTEGER NOT NULL DEFAULT 0, credential_revision INTEGER NOT NULL DEFAULT 0, last_refresh_revision INTEGER NOT NULL DEFAULT -1, last_used TIMESTAMP, last_error TEXT, daily_quota INTEGER NOT NULL DEFAULT 0, used_today INTEGER NOT NULL DEFAULT 0, quota_reset_at TIMESTAMP NOT NULL, priority INTEGER NOT NULL DEFAULT 0, weight INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, request_revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE account_pool_rules (id TEXT PRIMARY KEY, user_id TEXT, provider TEXT, model_pattern TEXT NOT NULL, allowed_account_ids TEXT NOT NULL, selection_strategy TEXT NOT NULL CHECK (selection_strategy IN ('round_robin', 'priority', 'least_used')), enable_fallback BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE usage_logs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, upstream_account_id TEXT NOT NULL, timestamp TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, model TEXT NOT NULL, provider TEXT NOT NULL, input_tokens INTEGER NOT NULL DEFAULT 0, output_tokens INTEGER NOT NULL DEFAULT 0, success BOOLEAN NOT NULL, error TEXT, latency_ms INTEGER NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (upstream_account_id) REFERENCES upstream_accounts(id) ON DELETE CASCADE);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE INDEX idx_usage_logs_user_timestamp ON usage_logs(user_id, timestamp DESC);
CREATE INDEX idx_usage_logs_account_timestamp ON usage_logs(upstream_account_id, timestamp DESC);
CREATE INDEX idx_upstream_accounts_status ON upstream_accounts(status, provider);
CREATE TRIGGER upstream_credential_revision AFTER UPDATE OF credentials, credential_type ON upstream_accounts BEGIN UPDATE upstream_accounts SET credential_revision = credential_revision + 1 WHERE id = NEW.id; END;
CREATE TRIGGER upstream_state_revision AFTER UPDATE OF status, last_error ON upstream_accounts WHEN NEW.request_revision = OLD.request_revision BEGIN UPDATE upstream_accounts SET state_revision = state_revision + 1 WHERE id = NEW.id; END;
CREATE TABLE oauth_refresh_intents (token_fingerprint TEXT PRIMARY KEY, attempt_id TEXT NOT NULL, account_id TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE user_daily_quota (user_id TEXT NOT NULL REFERENCES users(id), day TEXT NOT NULL, used INTEGER NOT NULL CHECK (used >= 0), PRIMARY KEY (user_id, day));
CREATE TABLE quota_migration_marker (id INTEGER PRIMARY KEY CHECK (id = 1));
CREATE TRIGGER protect_user_usage_history BEFORE DELETE ON users WHEN EXISTS (SELECT 1 FROM usage_logs WHERE user_id = OLD.id) OR EXISTS (SELECT 1 FROM user_daily_quota WHERE user_id = OLD.id) BEGIN SELECT RAISE(ABORT, 'user has usage history'); END;
CREATE TRIGGER protect_account_usage_history BEFORE DELETE ON upstream_accounts WHEN EXISTS (SELECT 1 FROM usage_logs WHERE upstream_account_id = OLD.id) BEGIN SELECT RAISE(ABORT, 'account has usage history'); END;
